<?php $s=site_settings();$messages=qall('SELECT * FROM contact_messages ORDER BY id DESC LIMIT 50');$visits=qall('SELECT page_name,COUNT(*) visits FROM page_visits WHERE visited_on>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) GROUP BY page_name ORDER BY visits DESC LIMIT 10'); ?>
<div class="erp-grid"><section class="erp-card"><div class="erp-card-head"><div><h2>Pengaturan Website</h2><p>Identitas toko, kontak, dan konten Tentang Kami.</p></div></div><form method="post" class="erp-form"><input type="hidden" name="action" value="admin_settings_save"><input type="hidden" name="csrf" value="<?= e(compliance_csrf()) ?>"><?php foreach(['store_name'=>'Nama toko','contact_email'=>'Email','contact_phone'=>'Telepon','contact_address'=>'Alamat'] as $key=>$label): ?><label><?= $label ?><input name="<?= $key ?>" value="<?= e($s[$key]??'') ?>" required></label><?php endforeach; ?><label>Visi<textarea name="vision" required><?= e($s['vision']??'') ?></textarea></label><label>Misi<textarea name="mission" required><?= e($s['mission']??'') ?></textarea></label><button class="erp-btn">Simpan pengaturan</button></form></section><section class="erp-card erp-wide"><h2>Pesan kontak terbaru</h2><div class="erp-table-wrap"><table><thead><tr><th>Pengirim</th><th>Kontak</th><th>Pesan</th><th>Waktu</th></tr></thead><tbody><?php foreach($messages as $m): ?><tr><td><?= e($m['name']) ?></td><td><?= e($m['email']) ?><small><?= e($m['phone']) ?></small></td><td><?= e($m['message']) ?></td><td><?= e($m['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><h2>Pengunjung 30 hari terakhir</h2><?php foreach($visits as $v): ?><p><?= e($v['page_name']) ?>: <b><?= (int)$v['visits'] ?></b> kunjungan</p><?php endforeach; ?></section></div>
